/**
 * Fixtures: core/gestures
 * Requirements: NAV-006..NAV-017, ARC-006, ANN-008
 * Expected values were computed with an independent reference implementation (docs/reference/core-reference.mjs
 * and docs/reference/core-reference-2.mjs). Compare floating-point numbers with a tolerance (toBeCloseTo(expected, 9)).
 * Do not edit expected values without recording the reason in docs/changelog.md.
 */
import type {
  GestureLimits, PointerContext, PointerPolicy, PointerSample, TrackClass, TapZone, WheelEventInput, WheelState,
} from '../gestures';

/** Values of tunables.gestures at the time of writing; tests use these constants, not tunables.ts. */
export const gestureLimits: GestureLimits = {
  tapMaxDurationMs: 250,
  tapMaxMovePx: 10,
  swipeMinDistanceFraction: 0.15,
  swipeMaxAngleDeg: 30,
  swipeMinVelocityPxPerMs: 0.3,
};
export const tapZones = { left: 0.3, center: 0.4, right: 0.3 } as const;
export const wheelConfig = { stepThresholdPx: 60, idleResetMs: 150, cooldownMs: 350, lineHeightPx: 40, pageHeightPx: 800 } as const;

